INSERT INTO blog(title,slug,description,content,image_banner,seo_title,meta_description,num_view,created_date,update_date,archived) VALUES('Cẩm nang chọn giày đi bộ','sports-cam-nang-di-bo','Hướng dẫn chọn giày phù hợp nhu cầu vận động.','<h2>Chọn giày theo hoạt động</h2><p>Kiểm tra độ vừa chân, bảng size riêng của hãng và mặt sân sử dụng. Nên thử cả hai chân, dành khoảng trống đầu ngón phù hợp.</p><p>Vệ sinh nhẹ nhàng, hong khô tự nhiên; không dùng thông số minh họa trong catalog để thay hướng dẫn của nhà sản xuất.</p>','/image/sports/di-bo.svg','Cẩm nang giày đi bộ','Cẩm nang thể thao F6S.',0,NOW(6),NOW(6),b'0');
